function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // character 1
  ctx.beginPath();
  ctx.arc(W/4 + Math.sin(t)*20, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 + Math.sin(t)*20, H/2 + 20);
  ctx.lineTo(W/4 + Math.sin(t)*20, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 + Math.sin(t)*20, H/2 + 50);
  ctx.lineTo(W/4 + Math.sin(t)*20 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 + Math.sin(t)*20, H/2 + 50);
  ctx.lineTo(W/4 + Math.sin(t)*20 + 30, H/2 + 70);
  ctx.stroke();

  // character 2
  ctx.beginPath();
  ctx.arc(W - W/4 + Math.cos(t)*20, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4 + Math.cos(t)*20, H/2 + 20);
  ctx.lineTo(W - W/4 + Math.cos(t)*20, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4 + Math.cos(t)*20, H/2 + 50);
  ctx.lineTo(W - W/4 + Math.cos(t)*20 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4 + Math.cos(t)*20, H/2 + 50);
  ctx.lineTo(W - W/4 + Math.cos(t)*20 + 30, H/2 + 70);
  ctx.stroke();

  // moving towards each other
  if (Math.sin(t) > 0) {
    ctx.beginPath();
    ctx.moveTo(W/2 - Math.abs(Math.sin(t))*50, H/2 + 50);
    ctx.lineTo(W/2 + Math.abs(Math.sin(t))*50, H/2 + 50);
    ctx.stroke();
  } else {
    ctx.beginPath();
    ctx.moveTo(W/2 - Math.abs(Math.cos(t))*50, H/2 + 50);
    ctx.lineTo(W/2 + Math.abs(Math.cos(t))*50, H/2 + 50);
    ctx.stroke();
  }

  ctx.restore();
}
